import{_ as a,o as i,c as n,a2 as e}from"./chunks/framework.5akMI7mQ.js";const c=JSON.parse('{"title":"Daemon Overview (wednesd)","description":"","frontmatter":{},"headers":[],"relativePath":"cli-reference/wednesd.md","filePath":"cli-reference/wednesd.md","lastUpdated":1792429063000}'),t={name:"cli-reference/wednesd.md"};function l(p,s,o,d,h,r){return i(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="daemon-overview-wednesd" tabindex="-1">Daemon Overview (<code>wednesd</code>) <a class="header-anchor" href="#daemon-overview-wednesd" aria-label="Permalink to &quot;Daemon Overview (\`wednesd\`)&quot;">​</a></h1><p><code>wednesd</code> is the core daemon and CLI tool for <strong>Wednes Serverless Engine</strong>.</p><p>It orchestrates the WebAssembly runtime, validates manifests, serves HTTP and QUIC gateways, enforces per-function isolation, and executes functions adhering to the <code>wednes:function@0.1.0</code> component ABI.</p><hr><h2 id="installation-verification" tabindex="-1">Installation &amp; Verification <a class="header-anchor" href="#installation-verification" aria-label="Permalink to &quot;Installation &amp; Verification&quot;">​</a></h2><p>Build from source or download release binaries:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Build optimized release binary with cargo</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cargo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> build</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --release</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bin</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wednesd</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Verify binary version and build info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./target/release/wednesd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><p>Output:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Wednes Engine Function Daemon</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Usage: wednesd [OPTIONS] [COMMAND]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Commands:</span></span>
<span class="line"><span>  init    Initialize a new serverless function project</span></span>
<span class="line"><span>  dev     Start local development server with file watching and live reload</span></span>
<span class="line"><span>  deploy  Deploy a function manifest to an atomic file registry</span></span>
<span class="line"><span>  run     Start the production daemon serving functions from a registry</span></span>
<span class="line"><span>  help    Print this message or the help of the given subcommand(s)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Options:</span></span>
<span class="line"><span>  -l, --listen &lt;LISTEN&gt;                      [default: 127.0.0.1:8080]</span></span>
<span class="line"><span>  -w, --wasm &lt;WASM&gt;                          </span></span>
<span class="line"><span>  -i, --id &lt;ID&gt;                              [default: hello]</span></span>
<span class="line"><span>      --global-concurrency &lt;GLOBAL_CONCURRENCY&gt;  [default: 100]</span></span>
<span class="line"><span>      --memory-budget-mb &lt;MEMORY_BUDGET_MB&gt;      [default: 1200]</span></span>
<span class="line"><span>      --default-concurrency &lt;DEFAULT_CONCURRENCY&gt;  [default: 16]</span></span>
<span class="line"><span>      --log-json                             </span></span>
<span class="line"><span>      --http3                                </span></span>
<span class="line"><span>  -h, --help                                 Print help</span></span>
<span class="line"><span>  -V, --version                              Print version</span></span></code></pre></div><hr><h2 id="two-operating-modes" tabindex="-1">Two Operating Modes <a class="header-anchor" href="#two-operating-modes" aria-label="Permalink to &quot;Two Operating Modes&quot;">​</a></h2><p><code>wednesd</code> operates in two primary modes:</p><h3 id="_1-registry-mode-production-recommended" tabindex="-1">1. Registry Mode (Production Recommended) <a class="header-anchor" href="#_1-registry-mode-production-recommended" aria-label="Permalink to &quot;1. Registry Mode (Production Recommended)&quot;">​</a></h3><p>In registry mode, <code>wednesd</code> reads a multi-function registry file (<code>registry.json</code>) containing precompiled function metadata, resource limits, and routing paths. This mode supports zero-downtime atomic updates, multi-function concurrency pools, and strict memory budgets.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Run production daemon serving all functions from registry.json</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wednesd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./registry.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 0.0.0.0:8080</span></span></code></pre></div><h3 id="_2-standalone-mode-development-legacy" tabindex="-1">2. Standalone Mode (Development / Legacy) <a class="header-anchor" href="#_2-standalone-mode-development-legacy" aria-label="Permalink to &quot;2. Standalone Mode (Development / Legacy)&quot;">​</a></h3><p>In standalone mode, <code>wednesd</code> loads a single <code>.wasm</code> component directly into memory on boot. This is ideal for rapid local testing or minimal single-purpose micro-daemons.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wednesd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --listen</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 127.0.0.1:8080</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --wasm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./hello.wasm</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --id</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> hello</span></span></code></pre></div><hr><h2 id="logging-observability" tabindex="-1">Logging &amp; Observability <a class="header-anchor" href="#logging-observability" aria-label="Permalink to &quot;Logging &amp; Observability&quot;">​</a></h2><p>By default, <code>wednesd</code> outputs human-readable console logs using <code>tracing-subscriber</code>.</p><p>For cloud-native production environments (Datadog, Grafana Loki, FluentBit), enable structured JSON output with <code>--log-json</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wednesd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --registry</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./registry.json</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --log-json</span></span></code></pre></div><p>Sample JSON log stream:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-19T10:15:30.123Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;INFO&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fields&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Loaded function &#39;auth-validator&#39;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wednesd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;timestamp&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2026-10-19T10:15:30.125Z&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;level&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;INFO&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;fields&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:{</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wednesd HTTP gateway listening on 127.0.0.1:8080&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;target&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;wednesd&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div>`,25)])])}const g=a(t,[["render",l]]);export{c as __pageData,g as default};
